package com.agriconnect.logistics;
import static org.assertj.core.api.Assertions.*;import java.util.*;import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.core.simple.JdbcClient;
class ShipmentWorkflowTest{@Test void duplicateOrderCreatesOneShipment(){JdbcDataSource ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:ship;MODE=PostgreSQL;DB_CLOSE_DELAY=-1");JdbcTemplate j=new JdbcTemplate(ds);j.execute("create table shipments(id bigint generated by default as identity primary key,order_id bigint unique,buyer_id bigint,farmer_ids varchar(255),logistics_user_id bigint,pickup_address varchar(255),delivery_address varchar(255),status varchar(20),shipped_at timestamp with time zone,delivered_at timestamp with time zone)");ShipmentController c=new ShipmentController(JdbcClient.create(ds),"key");Map<String,Object>x=new HashMap<>();x.put("orderId",1);x.put("buyerId",2);x.put("farmerIds","3");x.put("logisticsUserId",4);x.put("pickupAddress","A");x.put("deliveryAddress","B");c.create("key",x);c.create("key",x);assertThat(j.queryForObject("select count(*) from shipments",Integer.class)).isEqualTo(1);}}
